"""Evaluation helpers (R9, R10). Labels are consumed only here, after scores.

auc_pr uses sklearn's average_precision_score as the primary value (ADBench
convention) and the trapezoidal area of the precision-recall curve as a
secondary check. No paper numbers appear in this module.
"""
from __future__ import annotations

import numpy as np
from sklearn.metrics import (average_precision_score, precision_recall_curve,
                             roc_auc_score)


def evaluate_scores(scores: np.ndarray, y: np.ndarray) -> dict:
    scores = np.asarray(scores, dtype=np.float64)
    y = np.asarray(y, dtype=np.int64)
    roc = float(roc_auc_score(y, scores))
    ap = float(average_precision_score(y, scores))
    prec, rec, _ = precision_recall_curve(y, scores)
    pr_trap = float(-np.sum(np.diff(rec) * (prec[1:] + prec[:-1]) / 2.0))
    return {"auc_roc": roc, "auc_pr": ap, "auc_pr_trapz": pr_trap,
            "n": int(len(y)), "n_pos": int(y.sum())}


def summarize(values) -> dict:
    """mean / std (ddof=1, sample std over repeats) / min / max."""
    v = np.asarray(list(values), dtype=np.float64)
    if v.size == 0:
        return {"mean": float("nan"), "std": float("nan"), "min": float("nan"),
                "max": float("nan"), "n": 0}
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }

