def as_float(text):
    """Extract the first number from a descriptive plan/contract field."""
    if isinstance(text, (int, float)):
        return float(text)
    try:
        for tok in str(text).replace(",", " ").split():
            tok2 = tok.strip("()[]:,;")
            try:
                return float(tok2)
            except ValueError:
                continue
    except Exception:  # noqa: BLE001
        pass
    return None


def verdict(value: float, target, tol) -> str:
    target_f, tol_f = as_float(target), as_float(tol)
    if target_f is None or tol_f is None:
        return "no_target_available"
    return "PASS" if abs(value - target_f) <= tol_f else "FAIL"

